  [PseudoEMetricSpace α] [CompleteSpace α] [SecondCountableTopology α] [BorelSpace α]
  (P : Measure α) [IsFiniteMeasure P] :
  P.InnerRegular (fun s => IsCompact s ∧ IsClosed s) MeasurableSet
\end{minted}

